        "Значимое приглашение рассматривается в разных разговорах и окружениях. Собеседники нужны как слушатели: процесс позволяет заметить, как меняется собственное восприятие, без передачи им решения. Срок определяется переживанием вопроса, универсального числа дней здесь нет."
