        "Идея может объединить впечатления, напомнить историю или показать событие с неожиданной стороны. Ворота 11 описывают такую работу абстрактного ума: свободное движение образов и их оценку. Здесь возникает множество возможностей понимания, каждая из которых способна стать полезной частью разговора, обучения или культурного опыта.",
        "В канале 11–56 идеи находят выражение через рассказ и стимуляцию воображения. Каждому образу не обязательно становиться личным планом действий: одни идеи предназначены для обсуждения, другие созревают со временем. Ценность этого материала раскрывается в обмене, когда другой человек получает возможность увидеть собственный опыт шире."
