        "В канале 12–22 открытость соединяется с осторожным выражением. Когда настроения для встречи нет, прежняя лёгкость может исчезать, а слова восприниматься иначе. Эмоциональный процесс требует времени: услышанное способно раскрыть свой смысл позднее, по мере смены состояния и возвращения к тому, что прозвучало."
