        "С воротами 20 сила получает прямой выход в действие настоящего момента, с 57 соединяется с интуицией, с 10 поддерживает собственное поведение. Одна лишь мощность не выбирает подходящий объект приложения. Важно различать наличие энергии и то, куда она действительно включена в механике конкретной карты."
