        "В канале 35–36 перемены соединены с эмоциональной интенсивностью незнакомого. Каждая новая история приносит собственные неожиданности, поэтому заранее рассчитанный итог может не состояться. Если всё время искать следующее впечатление, прежнее не успевает раскрыть значение; завершение и осмысление дают перемене содержательность."
