        "В канале 35–36 переживание получает возможность превратиться в перемену и позднее быть выраженным. Прожитая трудность способна углубить понимание чужой уязвимости. При этом интенсивность сама по себе ещё не означает освоения: опыт обретает смысл по мере того, как чувства меняются и обнаруживается, что действительно произошло."
