        "В канале 37–40 эмоциональная связь встречается с трудом и потребностью в вознаграждении. Договор может оставаться негласным, но его нарушение всё равно чувствуется. Прояснение того, что каждый даёт и на что рассчитывает, помогает сохранить теплоту, не превращая принадлежность в неограниченное требование постоянной отдачи."
