        "В канале 28–38 давление встречается с интуитивным различением риска и смысла. Препятствие может собрать силы, но постоянная война со всем подряд расходует их без ясного результата. Разница между упрямством по привычке и защитой значимого становится видна по тому, чему в итоге служит продолжение борьбы."
