        "В канале 23–43 прозрение получает возможность словесного выражения. Между внутренней ясностью и понятностью для слушателя есть расстояние: требуется язык и подходящая восприимчивость. Если высказать понимание раньше, чем оно нашло форму, его необычность легко принять за бессвязность; ясное объяснение помогает раскрыть практическое содержание."
